  'vault.explainer':
    'Сейф — це не файл і не має нічого спільного з вашим .env. Це зашифроване сховище «ключ/значення», яке живе лише на цій машині — записи привʼязані до репозиторію (або лишаються глобальними), але вони ніколи не потрапляють у репозиторій і ніколи не комітяться та не пушаться. Тримайте секрети під рукою: покажіть, скопіюйте значення або натисніть «Копіювати як .env», щоб вставити цілий набір там, де він справді потрібен.',
