  'remoteAuth.rejected': 'Хост відхилив ці облікові дані — термін минув або їх відкликано. Увійдіть знову в Налаштування → Інтеграції.',
  'remoteAuth.linkMissing': "Прив'язаний обліковий запис {login} більше не виконав вхід на цьому комп'ютері. Увійдіть знову в Налаштування → Інтеграції.",
  'remoteAuth.needsUsername': 'Цей віддалений репозиторій використовує особистий токен Bitbucket Data Center, якому потрібне ім’я користувача: без нього git не може його надіслати. Вкажіть ім’я користувача для цього сервера в Налаштування → Інтеграції або виберіть тип «Токен проєкту або репозиторію», якщо це він.',
  'remoteAuth.noPush': 'Ці області не дозволяють push. GitHub потребує repo (або public_repo), GitLab — write_repository.',
  'remoteAuth.noWorkflow': 'Без області workflow GitHub відхиляє push, що змінюють .github/workflows. Для входу через GitHub CLI виконайте `gh auth refresh -h github.com -s workflow`; для токена додайте область.',
  'remoteAuth.embedded': 'Пароль зберігається відкритим текстом у .git/config. Змініть віддалений репозиторій, щоб прибрати його з URL, і підключіть обліковий запис натомість.',
  'urlCred.authExplanation': 'URL віддаленого репозиторію «{remote}» містить збережений пароль або токен. Git використовує його замість токена вашого профілю, і він зберігається відкритим текстом у .git/config цього репозиторію.',
  'urlCred.removeAction': 'Прибрати з URL…',
  'urlCred.confirmTitle': 'Прибрати збережений токен із «{remote}»?',
  'urlCred.confirmMessage': 'Пароль або токен буде прибрано з URL «{remote}» у .git/config — і для fetch, і для push. Після цього застосунок використовує токен профілю репозиторію або власний credential helper git.',
  'urlCred.confirmNoUndo': 'Скасувати не можна: скасування знову записало б секрет відкритим текстом.',
  'urlCred.confirmRevoke': 'Якщо старий токен ще може працювати, відкличте його на сервері: він був доступний для читання в цьому файлі.',
  'urlCred.confirmOk': 'Прибрати',
