  'urlCred.retry': 'Повторити',
  'urlCred.chipTitle': 'URL цього віддаленого репозиторію містить збережений пароль; він має пріоритет над токеном вашого профілю.',
  'urlCred.noProfileToken': 'У вашому профілі немає токена для {host}. Після видалення fetch і push завершуватимуться помилкою, доки ви не додасте токен у «Налаштування → Інтеграції».',
  'urlCred.addTokenFirst': 'Спершу додати токен',
  'urlCred.chipAmbiguous': 'URL {remote} містить збережений пароль, але незрозуміло, де починається хост, тому його не прибрано автоматично. Натисніть, щоб змінити віддалений репозиторій.',
