  'gitError.remoteUrlAmbiguous': 'В URL віддаленого репозиторію «{remote}» незрозуміло, де починається хост, тому пароль не прибрано автоматично. Змініть репозиторій вручну.',
  'remoteAuth.noCred': 'Збережених облікових даних не знайдено. Публічні репозиторії можуть дозволяти анонімне читання.',
