  'rerere.intro': 'Git уміє запамʼятати, як ви розвʼязали конфлікт, і відтворити це наступного разу, коли той самий конфлікт зʼявиться знову. Це окупається на довгій гілці, яку раз за разом ребейзять через те саме зіткнення — ви розвʼязуєте його один раз.',
