  'attrs.intro':
    '.gitattributes — це те, як репозиторій навчає git про власні файли: які з них двійкові, які треба зчіплювати замість конфліктувати, які не потрапляють в архів, які закінчення рядків використовувати. Він подорожує разом із клоном, тож виправлення тут — це виправлення для всіх.',
