    'Правила надходять з кількох файлів, і перемагає останній збіг, тож читати їх — це вгадування. Тут ми питаємо сам git.',
  'attrs.check': 'Перевірити',
  'attrs.checkNothing': 'Для цього шляху нічого не задано.',
  'attrs.driversTitle': 'Драйвери diff',
  'attrs.driversHint':
    'Драйвер diff перетворює нечитний файл на текст до того, як git його порівняє, — тож документ Word чи таблиця мають читану історію. Word, Excel і JSON використовують конвертер, що постачається з GitHuttBr; решта пропонується, якщо встановлена, інакше показана сірим.',
