  'attrs.driverEphemeralHint': "Цей конвертер налаштувала версія GitHuttBr у форматі AppImage. Її тека в /tmp зникає після виходу із застосунку, і будь-який інший користувач цього комп’ютера може покласти туди програму, яку запустить ваш наступний git diff. Видаліть його.",
  'attrs.driverStale': 'конвертер старший за 4.39',
  'attrs.driverStaleHint': 'Це конвертер, який версії до 4.38 постачали під старою назвою застосунку. Застосунок сам перенаправляє такі драйвери на свій поточний конвертер, але цей перенаправити не вдалося: шлях AppImage змінюється з кожним запуском або конфігурацію не вдалося записати. Diff цих файлів не працює, якщо старе встановлення не лишилося на місці. Приберіть його, а потім знову додайте драйвер із пропозицій нижче.',
  'attrs.driverRemove': "Видалити",
  'attrs.bundledAppImage': "Недоступно в AppImage: конвертер GitHuttBr існує, лише доки застосунок запущений. Встановіть пакет .deb, щоб ним користуватися.",
  'attrs.filtersTitle': 'Фільтри clean/smudge',
