  'attrs.filterDangerTitle': 'Зберегти неперевірений фільтр?',
  'attrs.filterDangerMessage': 'Пробний запуск не зміг перевірити "{name}": команда завершилася помилкою, нічого не збіглося або прохід туди й назад не відтворює початкові байти. Якщо фільтр хибний, кожне витягання відповідних файлів може непомітно зіпсувати робоче дерево.',
