  'keychain.pointNoAccess': 'GitHuttBr не може прочитати нічого іншого у вашій ключниці. Система завжди віддає застосунку лише той запис, який він сам створив.',
  'keychain.pointLocal': 'Усе лишається на цій машині — жодної синхронізації, жодної хмари, нічого нікуди не надсилається.',
  'keychain.pointOptional': 'Необовʼязково: скажіть «ні», і GitHuttBr працюватиме далі. Ваші токени просто житимуть у памʼяті до виходу, а Сейф лишиться закритим.',
  'keychain.reasonAdopted': 'Ви вже зберігаєте облікові дані саме так — ось що це означає.',
  'keychain.whatHappensAdopted': 'Якщо продовжите, нічого не зміниться: GitHuttBr прочитає запис, який уже створив. Ваша операційна система може попросити підтвердження ще раз після оновлення, бо застосунок, який вона бачить, змінився.',
  'keychain.whatHappens': 'Якщо продовжите, ваша операційна система тепер попросить дозволити доступ до запису з назвою «GitHuttBr Safe Storage» — того, який GitHuttBr створює для себе.',
  'keychain.accept': 'Продовжити',
  'keychain.decline': 'Не зараз',
  'keychain.settingsTitle': 'Ключниця ОС',
  'keychain.statusGranted': 'Увімкнено — токени й записи Сейфа зашифровано ключницею вашої ОС.',
  'keychain.statusDeclined': 'Вимкнено — токени тримаються в памʼяті лише на час сеансу, а Сейф недоступний.',
  'keychain.tokenSessionOnly': 'Зберігається лише до закриття GitHuttBr: ключницю ОС вимкнено.',
  'keychain.tokenNoKeyring': 'Зберігається лише до закриття GitHuttBr: система не має ключниці для шифрування.',
  'keychain.tokenNotMoved': 'Зберігається лише до закриття GitHuttBr: він ще не потрапив до системної ключниці.',
  'keychain.tokenWeakBackend': 'Збережено лише до закриття GitHuttBr: зв’язка ключів не запущена, а просте сховище його не захистило б.',
  'keychain.tokenStoreUnreadable': 'Зберігається лише до закриття GitHuttBr: не вдалося прочитати збережені токени. Розблокуйте ключницю і спробуйте ще раз.',
  'keychain.storeUnreadable': 'GitHuttBr не зміг прочитати збережені токени — ключниця була заблокована або доступ заборонено. Їх не змінено. Розблокуйте ключницю і спробуйте ще раз; токени, додані тим часом, зберігаються лише до закриття застосунку.',
  'keychain.weakBackend': 'Зв’язка ключів не запущена (GNOME Keyring або KWallet), тому система використовує просте сховище, яке лише заплутує дані сталим паролем, а не захищає їх. Раніше збережені токени й далі читаються, але нові зберігаються лише до закриття застосунку; Сейф і далі зберігає туди. Встановіть або розблокуйте зв’язку ключів і перезапустіть GitHuttBr.',
  'keychain.replaceStore': 'Створити нове сховище токенів',
  'keychain.replaceStoreTitle': 'Створити нове сховище токенів?',
  'keychain.replaceStoreMessage': 'GitHuttBr перестане чекати на збережені токени, які не може прочитати, і створить нове сховище лише з токенами, введеними в цьому сеансі. Старий файл залишиться поруч як резервна копія на 30 днів, потім його буде видалено. Робіть це, лише якщо ці токени втрачено назавжди — наприклад, їх зберегла інша копія GitHuttBr.',
  'keychain.enableFailed': 'GitHuttBr не вдалося перенести токени до системної ключниці. Вони зберігаються лише до закриття застосунку.',
